const tls = require('tls');
const crypto = require('crypto');
const moment = require('moment-timezone');
const fetch = require('node-fetch');
const ytSearch = require('yt-search');
const { formatUptime, formatUptimeVerbose, extractNumber, progressBar } = require('../lib/helpers');

function buildCommand() {
  const __args = [['sslcheck', 'tlsinfo'], 'Network Tools', 'Check a site\'s SSL certificate details', async ({ sock, from, msg, args }) => {
  const host = (args[0] || '').replace(/^https?:\/\//, '').split('/')[0];
  if (!host) return sock.sendMessage(from, { text: 'Usage: .sslcheck example.com' }, { quoted: msg });
  try {
    const cert = await new Promise((resolve, reject) => {
      const socket = tls.connect(443, host, { servername: host, timeout: 5000 }, () => {
        resolve(socket.getPeerCertificate());
        socket.end();
      });
      socket.on('error', reject);
      socket.on('timeout', () => reject(new Error('timeout')));
    });
    await sock.sendMessage(from, { text: `🔒 *SSL for ${host}*\nIssuer: ${cert.issuer?.O || 'n/a'}\nValid to: ${cert.valid_to}` }, { quoted: msg });
  } catch (e) {
    await sock.sendMessage(from, { text: 'Could not check SSL certificate.' }, { quoted: msg });
  }
}];
  const [commandsArr, section, description, handler, opts = {}] = __args;
  return { commands: commandsArr, section, description, handler, ownerOnly: !!opts.ownerOnly };
}

module.exports = buildCommand();
